static void em_invalid_pdv_flags(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {
    uint32_t new_flag = 0x99; // invalid PDV flags (valid range: 0-3)
    replace_dicom_attribute(701, 12, &new_flag, 0);
    forward_packet();
}
